// A name says where else it is used: the declaration that introduced it and
// every expression that reaches it. A client that asks for the uses alone is
// not sent the declaration.
fn twice(a: UInt8) -> UInt8 {
    a + a
}

fn main() -> UInt8 {
    let total: UInt8 = twice(1)
    total + total
}
